-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/wordladder/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

-- Word Ladder for XTOS Licorice, API 2.0 (uses tools/gamekit).
--
-- Turn the start word into the target, one letter at a time; every step must be a word. A new
-- ladder every day: make_puzzles.py stores one a line ("cold cord card ward warm", a shortest
-- ladder), day N from 1 November 2026 plays line N, and the list starts over after the last one.
-- Every third day has five letters. Par is the length of the shortest ladder.
--
-- Tap a letter of the newest word (the one to change is framed), then a key: if the result is a
-- word it joins the ladder. Letters already in their place in the target are underlined. Undo
-- takes back the last step, Hint adds the next word of a shortest ladder from where you are.
-- Earlier days can be played too; each day's ladder is kept.

local W, H = kit.W, kit.H
local LADDER_Y, LADDER_BOTTOM = 92, 566
local CW, CGAP, RH = 52, 8, 50             -- letter cell, gap, row height
local STATUS_Y = 572
local KEY_Y, KEY_H, KEY_GAP = 600, 44, 6
local BTN_Y, BTN_H = 750, 46
local ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'

local today, pday = 0, 0
local puz = nil          -- { no, path = { words }, start, target, len, par }
local steps = {}         -- the words after the start, in order
local hinted = {}        -- step index -> true when Hint made it
local solved = false
local pos = 1            -- the letter of the newest word to change
local msg = nil
local saved = {}         -- day -> the saved line
local words = {}         -- length -> { word = true }
local ERR = nil

------------------------------------------------------------------ days

local function days_from_civil(y, m, d)
  y = m <= 2 and y - 1 or y
  local era = (y >= 0 and y or y - 399) // 400
  local yoe = y - era * 400
  local doy = (153 * (m > 2 and m - 3 or m + 9) + 2) // 5 + d - 1
  local doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
  return era * 146097 + doe - 719468
end
local START = days_from_civil(2026, 11, 1)

local function civil(z)
  z = z + 719468
  local era = (z >= 0 and z or z - 146096) // 146097
  local doe = z - era * 146097
  local yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
  local doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
  local mp = (5 * doy + 2) // 153
  local d = doy - (153 * mp + 2) // 5 + 1
  local m = mp < 10 and mp + 3 or mp - 9
  return yoe + era * 400 + (m <= 2 and 1 or 0), m, d
end

local MONTHS = { 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec' }
local WDAYS = { 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat' }
local function date_label(day)
  local _y, m, d = civil(day)
  return WDAYS[(day + 4) % 7 + 1] .. ' ' .. d .. ' ' .. MONTHS[m]
end

local function local_day()
  local ok, t = pcall(function() return ctx.clock:now() end)
  if not ok or type(t) ~= 'table' or not tonumber(t.epoch_sec) then return START end
  local e = math.floor(tonumber(t.epoch_sec))
  if tonumber(t.hour) then
    local wall = tonumber(t.hour) * 3600 + (tonumber(t.minute) or 0) * 60 + (tonumber(t.second) or 0)
    local off = (wall - e % 86400) % 86400
    if off > 14 * 3600 then off = off - 86400 end
    off = math.floor(off / 900 + 0.5) * 900
    return (e + off) // 86400
  end
  return e // 86400
end

------------------------------------------------------------------ data

-- each line of a data file to fn, until fn returns false
local function each_line(name, fn)
  local P = ctx.package
  if not P then return end
  local ok, r = pcall(function() return P:open_text(name, { max_bytes = 200000, max_line_bytes = 256 }) end)
  if not ok or r == nil or type(r) == 'string' then return end
  while true do
    local okl, l = pcall(function() return r:read_line() end)
    if not okl or l == nil or fn(l) == false then break end
  end
  pcall(function() r:close() end)
end

local count = nil
local function read_puzzle(n)
  local line, k = nil, 0
  each_line('puzzles.txt', function(l)
    if l:match('^%l+ ') then
      k = k + 1
      if k == n then line = l; if count then return false end end
    end
  end)
  if not count or k > count then count = math.max(count or 0, k) end
  return line
end

local function word_set(n)
  if not words[n] then
    local set = {}
    each_line('words' .. n .. '.txt', function(l) if #l == n then set[l:upper()] = true end end)
    words[n] = set
  end
  return words[n]
end

local function puzzle_no(day)
  if not count then read_puzzle(1) end
  if not count or count == 0 then return nil end
  return (day - START) % count + 1
end

local function load_puzzle(day)
  local no = puzzle_no(day)
  local line = no and read_puzzle(no)
  if not line then return nil end
  local path = {}
  for w in line:gmatch('%l+') do path[#path + 1] = w:upper() end
  if #path < 2 then return nil end
  return { no = no, path = path, start = path[1], target = path[#path], len = #path[1], par = #path - 1 }
end

------------------------------------------------------------------ storage

local function state_line()
  local h = {}
  for i = 1, #steps do h[i] = hinted[i] and '1' or '0' end
  return (#steps > 0 and table.concat(steps, ',') or '-') .. '\t' .. (#steps > 0 and table.concat(h) or '-') .. '\t' .. (solved and 1 or 0)
end

local function save()
  if puz then saved[pday] = state_line() end
  local days = {}
  for d in pairs(saved) do days[#days + 1] = d end
  table.sort(days)
  local t = {}
  for k = math.max(1, #days - 400), #days do t[#t + 1] = days[k] .. '\t' .. saved[days[k]] end
  kit.write('days.txt', table.concat(t, '\n'))
end

local function load_saved()
  for d, rest in (kit.read('days.txt') or ''):gmatch('(%-?%d+)\t([^\n]*)') do saved[tonumber(d)] = rest end
end

------------------------------------------------------------------ play

local function current() return steps[#steps] or (puz and puz.start) end

local function hint_count()
  local n = 0
  for _k in pairs(hinted) do n = n + 1 end
  return n
end

-- the first letter of the newest word that differs from the target
local function first_open()
  local w = current()
  for i = 1, puz.len do if w:sub(i, i) ~= puz.target:sub(i, i) then return i end end
  return 1
end

local function open_day(day)
  local p = load_puzzle(day)
  if not p then ERR = 'no puzzles in the package'; return end
  puz, pday = p, day
  steps, hinted, solved, msg = {}, {}, false, nil
  word_set(p.len)
  local s = saved[day]
  if s then
    local ws, h, sv = s:match('^(%S+)\t(%S+)\t(%d)')
    if ws and ws ~= '-' then
      for w in ws:gmatch('%u+') do steps[#steps + 1] = w end
      for i = 1, #steps do if h:sub(i, i) == '1' then hinted[i] = true end end
    end
    solved = sv == '1'
  end
  pos = first_open()
  if solved then msg = 'Solved in ' .. #steps .. ' steps (par ' .. puz.par .. ').' end
end

local function finish()
  if current() == puz.target then
    solved = true
    local h = hint_count()
    msg = 'Solved in ' .. #steps .. ' steps (par ' .. puz.par .. ')' .. (h > 0 and (', hints ' .. h) or '') .. '.'
  else
    pos = first_open()
  end
end

local function in_ladder(w)
  if w == puz.start then return true end
  for _k, s in ipairs(steps) do if s == w then return true end end
  return false
end

local function play(letter)
  if solved or not puz then return end
  local w = current()
  local cand = w:sub(1, pos - 1) .. letter .. w:sub(pos + 1)
  if cand == w then return end
  if not word_set(puz.len)[cand] then msg = cand .. ' is not in the word list.'; return end
  if in_ladder(cand) then msg = cand .. ' is already in the ladder.'; return end
  steps[#steps + 1] = cand
  msg = nil
  finish()
  kit.moved()
  save()
end

local function undo()
  if #steps == 0 then return end
  hinted[#steps] = nil
  steps[#steps] = nil
  solved, msg = false, nil
  pos = first_open()
  save()
end

-- distances to the target over every word of this length, for a hint off the stored ladder
local function neighbours(w, set)
  local out = {}
  for i = 1, #w do
    for k = 1, 26 do
      local c = ALPHA:sub(k, k)
      if c ~= w:sub(i, i) then
        local v = w:sub(1, i - 1) .. c .. w:sub(i + 1)
        if set[v] then out[#out + 1] = v end
      end
    end
  end
  return out
end

local function next_word()
  local w = current()
  for i = 1, #puz.path - 1 do if puz.path[i] == w then return puz.path[i + 1] end end
  -- off the stored ladder: a breadth-first search from here to the target (tens of ms in the
  -- preview, which times Lua at device speed; more time asked for all the same)
  pcall(function() ctx.budget:extend() end)
  local set = word_set(puz.len)
  local prev, queue, head = { [w] = false }, { w }, 1
  while head <= #queue do
    local x = queue[head]; head = head + 1
    if x == puz.target then
      local y = x
      while prev[y] and prev[y] ~= w do y = prev[y] end
      return y
    end
    for _k, v in ipairs(neighbours(x, set)) do
      if prev[v] == nil then prev[v] = x; queue[#queue + 1] = v end
    end
  end
  return nil
end

local function hint()
  if solved or not puz then return end
  local nxt = next_word()
  if not nxt then msg = 'No ladder from here: Undo a step.'; return end
  steps[#steps + 1] = nxt
  hinted[#steps] = true
  msg = 'Hint: ' .. nxt
  finish()
  save()
end

------------------------------------------------------------------ drawing

-- the rows shown: the start, the steps (the last ones when there are many) and the target
local MAX_ROWS = (LADDER_BOTTOM - LADDER_Y) // RH
local function rows()
  local out = { { w = puz.start, kind = 'start' } }
  local room = MAX_ROWS - 2
  local first = math.max(1, #steps - room + 1)
  if first > 1 then
    out[#out + 1] = { gap = first - 1 }
    first = first + 1
  end
  for i = first, #steps do out[#out + 1] = { w = steps[i], kind = 'step', i = i } end
  if not solved then out[#out + 1] = { w = puz.target, kind = 'target' } end
  return out
end

local function word_x()
  return (W - (puz.len * CW + (puz.len - 1) * CGAP)) // 2
end
local function cell_x(i) return word_x() + (i - 1) * (CW + CGAP) end

-- the y of the newest word (the one being changed)
local function current_y()
  local rs = rows()
  for k, r in ipairs(rs) do
    if (r.kind == 'step' and r.i == #steps) or (#steps == 0 and r.kind == 'start') then return LADDER_Y + (k - 1) * RH end
  end
  return LADDER_Y
end

local function key_rect(k)        -- k from 1 to 26
  local row, col = (k - 1) // 9, (k - 1) % 9
  local kw = (W - 24 - 8 * KEY_GAP) // 9
  local x0 = row == 2 and 12 + (kw + KEY_GAP) // 2 or 12
  return x0 + col * (kw + KEY_GAP), KEY_Y + row * (KEY_H + KEY_GAP), kw, KEY_H
end

local BUTTONS = { 'Hint', 'Undo', 'Menu' }
local function button_rect(k)
  local bw = (W - 24 - 2 * 8) // 3
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

local function draw_word(gg, y, w, kind, framed)
  local big = kit.font('large')
  for i = 1, puz.len do
    local x, ch = cell_x(i), w:sub(i, i)
    if kind == 'target' then
      gg:rect(x, y, CW, RH - 8, { line_width = 1, radius = 6 })
    else
      gg:rect(x, y, CW, RH - 8, { line_width = (framed == i) and 4 or 1 })
    end
    gg:text(x + (CW - kit.width(big, ch)) // 2, y + (RH - 8 - kit.line_h('large')) // 2, ch, { font = big })
    if kind ~= 'target' and ch == puz.target:sub(i, i) then
      gg:line(x + 10, y + RH - 14, x + CW - 10, y + RH - 14, { line_width = 2 })
    end
  end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    gg:text(12, 12, 'Word Ladder', { font = kit.font('large') })
    if puz then
      local h = hint_count()
      gg:text(12, 52, kit.short(date_label(pday) .. (pday == today and '' or ' (earlier)') .. '  No. ' .. puz.no ..
        '  par ' .. puz.par .. (h > 0 and ('  hints ' .. h) or '') .. (solved and '  solved' or ''), 48), { font = kit.font('small') })
    end
    if kit.modal() then kit.draw_modal(gg); return end
    if not puz then
      if ERR then gg:text(12, 120, kit.short(ERR, 46), { font = kit.font('small') }) end
      return
    end
    local small = kit.font('small')
    for k, r in ipairs(rows()) do
      -- the target waits at the foot of the ladder
      local y = LADDER_Y + ((r.kind == 'target' and MAX_ROWS or k) - 1) * RH
      if r.gap then
        local s = '... ' .. r.gap .. ' more step' .. (r.gap == 1 and '' or 's') .. ' ...'
        gg:text((W - kit.width(small, s)) // 2, y + 12, s, { font = small })
      else
        local newest = (r.kind == 'step' and r.i == #steps) or (r.kind == 'start' and #steps == 0)
        draw_word(gg, y, r.w, r.kind, (newest and not solved) and pos or nil)
        local label = r.kind == 'start' and 'start' or r.kind == 'target' and 'target' or (r.i .. (hinted[r.i] and ' hint' or ''))
        gg:text(cell_x(puz.len) + CW + 12, y + 12, label, { font = small })
      end
    end
    if msg then gg:text(12, STATUS_Y, kit.short(msg, 46), { font = small }) end
    local med = kit.font('medium')
    for k = 1, 26 do
      local x, y, kw, kh = key_rect(k)
      local l = ALPHA:sub(k, k)
      gg:rect(x, y, kw, kh, { line_width = 1 })
      gg:text(x + (kw - kit.width(med, l)) // 2, y + (kh - kit.line_h('medium')) // 2, l, { font = med })
    end
    for k, b in ipairs(BUTTONS) do
      local x, y, bw, bh = button_rect(k)
      kit.button(gg, x, y, bw, bh, b)
    end
    if ERR then gg:text(12, H - 30, kit.short('ERR ' .. ERR, 48), { font = small }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function how_to()
  kit.show({ title = 'How to play', lines = {
    'Change the start word into the target, one letter at a time. Every step must be a word. Tap a letter of the newest word, then the new letter.',
    'Underlined letters are already where the target has them. Par is the shortest ladder. Undo takes back a step; Hint adds the next word of a shortest ladder.',
  }, rows = { { { 'Close', kit.close } } }, cancel = kit.close })
end

local function show_answer()
  kit.show({ title = 'A shortest ladder', lines = { table.concat(puz.path, ' > ') },
             rows = { { { 'Close', kit.close } } }, cancel = kit.close })
end

local function restart()
  steps, hinted, solved, msg = {}, {}, false, nil
  pos = first_open()
  save()
end

local function menu()
  local rows_ = {
    { { 'Today', function() kit.close(); save(); open_day(today) end, pday ~= today },
      { 'Earlier', function() kit.close(); save(); open_day(pday - 1) end } },
    { { 'Later', function() kit.close(); save(); open_day(pday + 1) end, pday < today },
      { 'Start over', function() kit.close(); restart() end } },
    { { 'Answer', show_answer }, { 'How to play', how_to } },
    { { 'Close', kit.close } },
  }
  kit.show({ title = 'Word Ladder', lines = { date_label(pday) .. ', ladder ' .. puz.no .. ' of ' .. (count or 0) .. ': ' ..
             puz.start .. ' to ' .. puz.target .. ', par ' .. puz.par .. '.' }, rows = rows_, cancel = kit.close })
end

local function in_rect(x, y, rx, ry, rw, rh) return x >= rx and x < rx + rw and y >= ry and y < ry + rh end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  if not puz then return end
  for k = 1, #BUTTONS do
    local bx, by, bw, bh = button_rect(k)
    if in_rect(x, y, bx, by, bw, bh) then
      if k == 1 then hint() elseif k == 2 then undo() else menu() end
      return
    end
  end
  for k = 1, 26 do
    local kx, ky, kw, kh = key_rect(k)
    if in_rect(x, y, kx - KEY_GAP // 2, ky - KEY_GAP // 2, kw + KEY_GAP, kh + KEY_GAP) then play(ALPHA:sub(k, k)); return end
  end
  if not solved then
    local cy = current_y()
    if y >= cy - 4 and y < cy + RH then
      for i = 1, puz.len do
        if in_rect(x, y, cell_x(i) - CGAP // 2, cy - 4, CW + CGAP, RH + 4) then pos = i; msg = nil; return end
      end
    end
  end
end

function on_input(c, ev)
  ERR = nil
  local handled = true
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and ev.key == 'back' then
      -- Back acts on its release (the host reads only the up event's answer): it closes a box;
      -- on the ladder it is left to the host, which offers to exit
      if ev.phase ~= 'up' and ev.phase ~= nil then return end
      if kit.modal() then
        if kit.modal().cancel then kit.modal().cancel() end
      else handled = false end
    elseif ev.type == 'key' and kit.key_accepted(ev) and not kit.modal() then
      if puz and (ev.key == 'down' or ev.key == 'right') then pos = pos % puz.len + 1
      elseif puz and (ev.key == 'up' or ev.key == 'left') then pos = (pos - 2) % puz.len + 1 end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return handled
end

function on_load(c)
  local ok, e = pcall(function()
    load_saved()
    today = local_day()
    open_day(today)
  end)
  if not ok then ERR = tostring(e) end
end
function on_leave() pcall(save) end

if rawget(_G, '__TEST') then
  __TEST.api = { puz = function() return puz end, steps = function() return steps end, solved = function() return solved end,
                 msg = function() return msg end, pos = function() return pos end, key_rect = key_rect, cell_x = cell_x,
                 current_y = current_y, open_day = open_day, pday = function() return pday end, START = START,
                 count = function() return count end, next_word = next_word, button_rect = button_rect, rows = rows }
end
